CREATE TABLE public.taxonomy (id text PRIMARY KEY, kind text NOT NULL CHECK (kind IN ('medium','specialty')), parent_id text REFERENCES public.taxonomy(id), slug text NOT NULL, label_en text NOT NULL, label_es text NOT NULL, sort_order integer NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','pending','hidden')), UNIQUE(kind,slug,parent_id));
GRANT SELECT ON public.taxonomy TO anon, authenticated; GRANT ALL ON public.taxonomy TO service_role;
ALTER TABLE public.taxonomy ENABLE ROW LEVEL SECURITY;
CREATE POLICY taxonomy_public ON public.taxonomy FOR SELECT TO anon,authenticated USING(status='active');
CREATE TABLE public.artist_mediums (artist_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, medium_id text NOT NULL REFERENCES public.taxonomy(id), is_main boolean NOT NULL DEFAULT false, PRIMARY KEY(artist_id,medium_id));
GRANT SELECT ON public.artist_mediums TO anon, authenticated; GRANT ALL ON public.artist_mediums TO service_role;
ALTER TABLE public.artist_mediums ENABLE ROW LEVEL SECURITY;
CREATE POLICY artist_mediums_read ON public.artist_mediums FOR SELECT TO anon,authenticated USING(artist_id=auth.uid() OR EXISTS(SELECT 1 FROM public.rooms WHERE id=artist_id AND published));
CREATE TABLE public.artist_specialties (artist_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, specialty_id text NOT NULL REFERENCES public.taxonomy(id), PRIMARY KEY(artist_id,specialty_id));
GRANT SELECT ON public.artist_specialties TO anon, authenticated; GRANT ALL ON public.artist_specialties TO service_role;
ALTER TABLE public.artist_specialties ENABLE ROW LEVEL SECURITY;
CREATE POLICY artist_specialties_read ON public.artist_specialties FOR SELECT TO anon,authenticated USING(artist_id=auth.uid() OR EXISTS(SELECT 1 FROM public.rooms WHERE id=artist_id AND published));
ALTER TABLE public.profiles ADD COLUMN interest_medium_ids text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.pieces ADD COLUMN medium_id text REFERENCES public.taxonomy(id), ADD COLUMN format_id text NOT NULL DEFAULT 'format:original', ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
COMMENT ON COLUMN public.pieces.medium IS 'DEPRECATED: use medium_id for taxonomy relationships; legacy display text remains for compatibility';
CREATE TABLE public.piece_specialties (piece_id text NOT NULL REFERENCES public.pieces(id) ON DELETE CASCADE, specialty_id text NOT NULL REFERENCES public.taxonomy(id), PRIMARY KEY(piece_id,specialty_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.piece_specialties TO authenticated; GRANT SELECT ON public.piece_specialties TO anon; GRANT ALL ON public.piece_specialties TO service_role;
ALTER TABLE public.piece_specialties ENABLE ROW LEVEL SECURITY;
CREATE POLICY piece_specialties_read ON public.piece_specialties FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.pieces WHERE id=piece_id));
CREATE POLICY piece_specialties_own ON public.piece_specialties FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.pieces WHERE id=piece_id AND artist=auth.uid()) AND public.has_role(auth.uid(),'artist')) WITH CHECK(EXISTS(SELECT 1 FROM public.pieces p JOIN public.taxonomy t ON t.parent_id=p.medium_id WHERE p.id=piece_id AND p.artist=auth.uid() AND t.id=specialty_id AND t.kind='specialty' AND t.status='active') AND public.has_role(auth.uid(),'artist'));
CREATE TABLE public.media_settings (id text PRIMARY KEY DEFAULT 'free' CHECK(id='free'), video_max_seconds integer NOT NULL DEFAULT 60, video_max_bytes bigint NOT NULL DEFAULT 104857600, audio_max_seconds integer NOT NULL DEFAULT 300, audio_max_bytes bigint NOT NULL DEFAULT 20971520);
GRANT SELECT ON public.media_settings TO anon,authenticated; GRANT ALL ON public.media_settings TO service_role;
ALTER TABLE public.media_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY media_settings_read ON public.media_settings FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.room_media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), artist uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, kind text NOT NULL CHECK(kind IN ('video','audio')), provider text NOT NULL CHECK(provider IN ('upload','youtube','vimeo','soundcloud','spotify','bandcamp')), url text NOT NULL, cover_image text, storage_path text, duration_s numeric, size_bytes bigint, sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.room_media TO authenticated; GRANT SELECT ON public.room_media TO anon; GRANT ALL ON public.room_media TO service_role;
ALTER TABLE public.room_media ENABLE ROW LEVEL SECURITY;
CREATE POLICY room_media_own ON public.room_media FOR ALL TO authenticated USING(artist=auth.uid() AND public.has_role(auth.uid(),'artist')) WITH CHECK(artist=auth.uid() AND public.has_role(auth.uid(),'artist'));
CREATE POLICY room_media_public ON public.room_media FOR SELECT TO anon,authenticated USING(EXISTS(SELECT 1 FROM public.rooms WHERE id=artist AND published AND 'media'=ANY(visible_sections)));
CREATE FUNCTION public.validate_room_media() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE s public.media_settings; BEGIN IF NEW.provider='upload' THEN SELECT * INTO s FROM public.media_settings WHERE id='free'; IF s.id IS NULL OR NEW.duration_s IS NULL OR NEW.size_bytes IS NULL OR NEW.duration_s<=0 OR NEW.size_bytes<=0 OR NEW.duration_s>(CASE NEW.kind WHEN 'video' THEN s.video_max_seconds ELSE s.audio_max_seconds END) OR NEW.size_bytes>(CASE NEW.kind WHEN 'video' THEN s.video_max_bytes ELSE s.audio_max_bytes END) THEN RAISE EXCEPTION 'Media exceeds upload limits'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_room_media BEFORE INSERT OR UPDATE ON public.room_media FOR EACH ROW EXECUTE FUNCTION public.validate_room_media();
CREATE POLICY room_media_storage_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='room-media');
CREATE POLICY room_media_storage_own ON storage.objects FOR ALL TO authenticated USING(bucket_id='room-media' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'artist')) WITH CHECK(bucket_id='room-media' AND (storage.foldername(name))[1]=auth.uid()::text AND public.has_role(auth.uid(),'artist'));
ALTER TABLE public.rooms ALTER COLUMN section_order SET DEFAULT ARRAY['work','media','shop','services','events','about','links','faq','contact'], ALTER COLUMN visible_sections SET DEFAULT ARRAY['work','media','shop','services','events','about','links','faq','contact'];
UPDATE public.rooms SET section_order=(SELECT array_agg(x ORDER BY ord) FROM (SELECT x,ord::numeric FROM unnest(section_order) WITH ORDINALITY AS a(x,ord) UNION ALL SELECT 'media',coalesce(array_position(section_order,'work'),0)+0.5) s),visible_sections=array_append(visible_sections,'media') WHERE NOT ('media'=ANY(section_order));
CREATE TABLE public.newsletter_signups (user_id uuid PRIMARY KEY, marketing_opt_in boolean NOT NULL DEFAULT false, consented_at timestamptz, source text NOT NULL CHECK(source IN ('collector quiz','artist quiz')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.newsletter_signups TO authenticated; GRANT ALL ON public.newsletter_signups TO service_role;
ALTER TABLE public.newsletter_signups ENABLE ROW LEVEL SECURITY;
CREATE POLICY newsletter_own ON public.newsletter_signups FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.save_artist_taxonomy(medium_ids text[], main_id text, specialty_ids text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); BEGIN IF u IS NULL OR NOT public.has_role(u,'artist') THEN RAISE EXCEPTION 'Artist account required'; END IF; PERFORM 1 FROM public.profiles WHERE id=u FOR UPDATE; IF cardinality(medium_ids) NOT BETWEEN 1 AND 3 OR cardinality(specialty_ids)>8 OR NOT main_id=ANY(medium_ids) OR (SELECT count(DISTINCT x) FROM unnest(medium_ids) x)<>cardinality(medium_ids) OR (SELECT count(DISTINCT x) FROM unnest(specialty_ids) x)<>cardinality(specialty_ids) THEN RAISE EXCEPTION 'Choose up to 3 mediums, one main, and 8 specialties'; END IF; IF EXISTS(SELECT 1 FROM unnest(medium_ids) x WHERE NOT EXISTS(SELECT 1 FROM public.taxonomy WHERE id=x AND kind='medium' AND status='active')) OR EXISTS(SELECT 1 FROM unnest(specialty_ids) x WHERE NOT EXISTS(SELECT 1 FROM public.taxonomy WHERE id=x AND kind='specialty' AND status='active' AND parent_id=ANY(medium_ids))) THEN RAISE EXCEPTION 'Specialties must match selected mediums'; END IF; DELETE FROM public.artist_specialties WHERE artist_id=u; DELETE FROM public.artist_mediums WHERE artist_id=u; INSERT INTO public.artist_mediums SELECT u,x,x=main_id FROM unnest(medium_ids) x; INSERT INTO public.artist_specialties SELECT u,x FROM unnest(specialty_ids) x; UPDATE public.profiles SET mediums=ARRAY(SELECT label_en FROM public.taxonomy WHERE id=ANY(medium_ids)),interest_medium_ids=medium_ids WHERE id=u; END $$;
REVOKE ALL ON FUNCTION public.save_artist_taxonomy(text[],text,text[]) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.save_artist_taxonomy(text[],text,text[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.complete_registration(payload jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u uuid:=auth.uid(); r public.app_role; h text; n text; mids text[]; specs text[]; opt boolean; BEGIN IF u IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; PERFORM 1 FROM public.profiles WHERE id=u FOR UPDATE; IF EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=u) THEN RETURN; END IF; r:=(payload->>'role')::public.app_role; h:=lower(payload->>'handle'); IF h IS NULL OR h='' THEN h:='collector_'||replace(u::text,'-',''); END IF; IF h !~ '^[a-z0-9_]+$' THEN RAISE EXCEPTION 'Invalid handle'; END IF; n:=trim(coalesce(payload->>'name','')); IF n='' AND r='collector' THEN SELECT split_part(email,'@',1) INTO n FROM auth.users WHERE id=u; END IF; IF coalesce(n,'')='' THEN RAISE EXCEPTION 'Name required'; END IF; mids:=ARRAY(SELECT DISTINCT x FROM jsonb_array_elements_text(coalesce(payload->'medium_ids','[]')) x); IF cardinality(mids)=0 THEN mids:=ARRAY(SELECT t.id FROM public.taxonomy t WHERE t.kind='medium' AND t.label_en IN (SELECT jsonb_array_elements_text(coalesce(payload->'mediums','[]')))); END IF; IF EXISTS(SELECT 1 FROM unnest(mids) x WHERE NOT EXISTS(SELECT 1 FROM public.taxonomy WHERE id=x AND kind='medium' AND status='active')) THEN RAISE EXCEPTION 'Invalid interests'; END IF; specs:=ARRAY(SELECT jsonb_array_elements_text(coalesce(payload->'specialty_ids','[]'))); opt:=coalesce((payload->>'marketing_opt_in')::boolean,false); UPDATE public.profiles SET display_name=n,handle=h,city=coalesce(payload->>'city',''),mediums=ARRAY(SELECT label_en FROM public.taxonomy WHERE id=ANY(mids)),interest_medium_ids=mids WHERE id=u; INSERT INTO public.user_roles VALUES(u,r); IF r='artist' THEN INSERT INTO public.rooms(id,handle,bio,room_color,wants,links,published) VALUES(u,h,coalesce(payload->>'bio',''),coalesce(payload->>'room','cream'),ARRAY(SELECT jsonb_array_elements_text(coalesce(payload->'wants','[]'))),coalesce(payload->'links','[]'),true); PERFORM public.save_artist_taxonomy(mids,coalesce(payload->>'main_medium_id',mids[1]),specs); END IF; INSERT INTO public.newsletter_signups(user_id,marketing_opt_in,consented_at,source) VALUES(u,opt,CASE WHEN opt THEN now() ELSE NULL END,CASE WHEN r='artist' THEN 'artist quiz' ELSE 'collector quiz' END); END $$;
CREATE FUNCTION public.public_piece_favorite_counts() RETURNS TABLE(piece_id text,favorite_count bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,count(f.piece) FROM public.pieces p JOIN public.rooms r ON r.id=p.artist AND r.published LEFT JOIN public.favorites f ON f.piece=p.id WHERE p.status<>'hidden' GROUP BY p.id $$;
REVOKE ALL ON FUNCTION public.public_piece_favorite_counts() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.public_piece_favorite_counts() TO anon,authenticated;